package org.apache.parquet.cli.json;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import org.apache.avro.Schema;
import org.apache.avro.SchemaBuilder;
import org.apache.avro.generic.GenericData;
import org.apache.avro.generic.GenericFixed;
import org.apache.avro.generic.GenericRecord;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.JsonNodeFactory;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;
import java.lang.reflect.Modifier;
import java.nio.ByteBuffer;
import java.util.List;
import java.util.Map;
import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertInstanceOf;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;

public class AvroJsonConvertToAvroTests {
  private static final GenericData MODEL = GenericData.get();
  private static final JsonNodeFactory JSON = JsonNodeFactory.instance;

  private static Object convertToAvro(GenericData model, JsonNode datum, Schema schema) {
    try {
      Method conversionMethod = null;
      for (Method method : AvroJson.class.getDeclaredMethods()) {
        if (method.getName().equals("convertToAvro")
            && (method.getParameterCount() == 2 || method.getParameterCount() == 3)) {
          conversionMethod = method;
          break;
        }
      }

      if (conversionMethod == null) {
        throw new NoSuchMethodException("convertToAvro");
      }

      conversionMethod.setAccessible(true);
      Class<?>[] parameterTypes = conversionMethod.getParameterTypes();
      Object[] arguments = new Object[parameterTypes.length];

      for (int i = 0; i < parameterTypes.length; i++) {
        if (GenericData.class.isAssignableFrom(parameterTypes[i])) {
          arguments[i] = model;
        } else if (JsonNode.class.isAssignableFrom(parameterTypes[i])) {
          arguments[i] = datum;
        } else if (Schema.class.isAssignableFrom(parameterTypes[i])) {
          arguments[i] = schema;
        } else {
          throw new IllegalStateException("Unexpected convertToAvro parameter");
        }
      }

      Object target =
          Modifier.isStatic(conversionMethod.getModifiers())
              ? null
              : AvroJson.class.getDeclaredConstructor().newInstance();
      return conversionMethod.invoke(target, arguments);
    } catch (InvocationTargetException e) {
      Throwable cause = e.getCause();
      if (cause instanceof RuntimeException) {
        throw (RuntimeException) cause;
      }
      if (cause instanceof Error) {
        throw (Error) cause;
      }
      throw new RuntimeException(cause);
    } catch (ReflectiveOperationException e) {
      throw new RuntimeException(e);
    }
  }

  @Test
  void convertsPrimitiveValuesAccordingToSchema() {
    assertEquals(42, convertToAvro(MODEL, JSON.numberNode(42), SchemaBuilder.builder().intType()));
    assertEquals(
        42L,
        convertToAvro(MODEL, JSON.numberNode(42L), SchemaBuilder.builder().longType()));
    assertEquals(
        3.5f,
        (Float) convertToAvro(MODEL, JSON.numberNode(3.5f), SchemaBuilder.builder().floatType()),
        0.0001f);
    assertEquals(
        7.25d,
        (Double)
            convertToAvro(MODEL, JSON.numberNode(7.25d), SchemaBuilder.builder().doubleType()),
        0.0001d);
    assertEquals(
        true,
        convertToAvro(MODEL, JSON.booleanNode(true), SchemaBuilder.builder().booleanType()));
    assertEquals(
        "parquet",
        convertToAvro(MODEL, JSON.textNode("parquet"), SchemaBuilder.builder().stringType()));
  }

  @Test
  void convertsRecordAndNestedContainersRecursively() {
    Schema schema =
        SchemaBuilder.record("Event")
            .fields()
            .requiredString("name")
            .name("tags")
            .type(SchemaBuilder.array().items(SchemaBuilder.builder().stringType()))
            .noDefault()
            .name("attributes")
            .type(SchemaBuilder.map().values(SchemaBuilder.builder().longType()))
            .noDefault()
            .endRecord();

    ObjectNode datum = JSON.objectNode();
    datum.put("name", "build");
    datum.putArray("tags").add("java").add("avro");
    datum.putObject("attributes").put("attempts", 3L).put("duration", 12L);

    GenericRecord record =
        assertInstanceOf(GenericRecord.class, convertToAvro(MODEL, datum, schema));

    assertEquals("build", record.get("name"));
    assertEquals(List.of("java", "avro"), record.get("tags"));

    Map<?, ?> attributes = assertInstanceOf(Map.class, record.get("attributes"));
    assertEquals(3L, attributes.get("attempts"));
    assertEquals(12L, attributes.get("duration"));
  }

  @Test
  void convertsEnumsBytesAndFixedValues() {
    Schema enumSchema = SchemaBuilder.enumeration("Status").symbols("READY", "DONE");
    Object enumValue = convertToAvro(MODEL, JSON.textNode("DONE"), enumSchema);
    assertEquals("DONE", enumValue.toString());

    Schema bytesSchema = SchemaBuilder.builder().bytesType();
    ByteBuffer bytes =
        assertInstanceOf(
            ByteBuffer.class,
            convertToAvro(MODEL, JSON.binaryNode(new byte[] {1, 2, 3}), bytesSchema));
    assertArrayEquals(new byte[] {1, 2, 3}, bytes.array());

    Schema fixedSchema = SchemaBuilder.fixed("Token").size(4);
    GenericFixed fixed =
        assertInstanceOf(
            GenericFixed.class,
            convertToAvro(
                MODEL, JSON.binaryNode(new byte[] {9, 8, 7, 6}), fixedSchema));
    assertArrayEquals(new byte[] {9, 8, 7, 6}, fixed.bytes());
  }

  @Test
  void convertsArraysMapsAndUnions() {
    Schema arraySchema = SchemaBuilder.array().items(SchemaBuilder.builder().intType());
    Object arrayResult =
        convertToAvro(MODEL, JSON.arrayNode().add(1).add(2).add(3), arraySchema);
    assertEquals(List.of(1, 2, 3), arrayResult);

    Schema mapSchema = SchemaBuilder.map().values(SchemaBuilder.builder().stringType());
    ObjectNode mapDatum = JSON.objectNode();
    mapDatum.put("first", "one");
    mapDatum.put("second", "two");
    Object mapResult = convertToAvro(MODEL, mapDatum, mapSchema);
    assertEquals(Map.of("first", "one", "second", "two"), mapResult);

    Schema unionSchema =
        SchemaBuilder.unionOf().intType().and().stringType().endUnion();
    assertEquals(
        "selected",
        convertToAvro(MODEL, JSON.textNode("selected"), unionSchema));
    assertEquals(
        19,
        convertToAvro(MODEL, JSON.numberNode(19), unionSchema));
  }

  @Test
  void nullDatumReturnsNullWithoutConsultingSchema() {
    assertNull(convertToAvro(null, null, null));
  }

  @Test
  void nullSchemaTypeProducesNullForAnyJsonDatum() {
    assertNull(
        convertToAvro(
            MODEL,
            JSON.textNode("ignored"),
            SchemaBuilder.builder().nullType()));
  }

  @Test
  void rejectsJsonKindsIncompatibleWithSchema() {
    assertThrows(
        RuntimeException.class,
        () ->
            convertToAvro(
                MODEL,
                JSON.textNode("not-an-int"),
                SchemaBuilder.builder().intType()));

    assertThrows(
        RuntimeException.class,
        () ->
            convertToAvro(
                MODEL,
                JSON.numberNode(4),
                SchemaBuilder.builder().booleanType()));

    assertThrows(
        RuntimeException.class,
        () ->
            convertToAvro(
                MODEL,
                JSON.objectNode(),
                SchemaBuilder.array().items(SchemaBuilder.builder().stringType())));
  }

  @Test
  void rejectsFixedBinaryWithIncorrectSize() {
    Schema fixedSchema = SchemaBuilder.fixed("ThreeBytes").size(3);

    assertThrows(
        RuntimeException.class,
        () -> convertToAvro(MODEL, JSON.binaryNode(new byte[] {1, 2}), fixedSchema));

    assertThrows(
        RuntimeException.class,
        () -> convertToAvro(MODEL, JSON.binaryNode(new byte[] {1, 2, 3, 4}), fixedSchema));
  }
}
